import "server-only";
import { and, desc, eq, sql } from "drizzle-orm";
import { computePeriodEnd, hmacSignature, timingSafeVerify } from "@/lib/payments-core";

export { computePeriodEnd, hmacSignature, timingSafeVerify };
import { db } from "@/db";
import {
  membershipPlans,
  paymentWebhookEvents,
  payments,
  subscriptions,
  users,
} from "@/db/schema";
import { notify } from "@/lib/notifications";
import { logActivity, logAudit } from "@/lib/logging";

/**
 * Payment provider abstraction.
 *
 * - "sandbox": development-mode provider. A signed "webhook" is generated by
 *   the server action to exercise the exact production verification path.
 *   Clearly labelled in the UI; never charges money.
 * - "sslcommerz" / "bkash": integration structures. They activate only when
 *   merchant credentials are configured via environment variables. Their
 *   webhook endpoints verify signatures/secrets before trusting any payload.
 */

export type PaymentProviderId = "sandbox" | "sslcommerz" | "bkash";

export function providerConfigured(provider: PaymentProviderId): { configured: boolean; note: string } {
  switch (provider) {
    case "sandbox":
      return { configured: true, note: "Sandbox mode — no real payment is processed." };
    case "sslcommerz":
      return process.env.SSLCZ_STORE_ID && process.env.SSLCZ_STORE_PASSWORD
        ? { configured: true, note: "SSLCommerz sandbox/live as configured." }
        : { configured: false, note: "Set SSLCZ_STORE_ID and SSLCZ_STORE_PASSWORD to enable." };
    case "bkash":
      return process.env.BKASH_APP_KEY && process.env.BKASH_APP_SECRET
        ? { configured: true, note: "bKash tokenized checkout as configured." }
        : { configured: false, note: "Set BKASH_APP_KEY and BKASH_APP_SECRET to enable." };
  }
}



/* -------------------------- Subscription activation -------------------------- */

export async function activateSubscription(args: {
  userId: string;
  planId: string;
  interval: "monthly" | "yearly";
  paymentId?: string;
  actorId?: string | null;
}) {
  const plan = await db.select().from(membershipPlans).where(eq(membershipPlans.id, args.planId)).limit(1);
  if (!plan[0]) throw new Error("Plan not found");

  // Expire existing active subscriptions (upgrade/downgrade replaces current plan)
  const existing = await db
    .select()
    .from(subscriptions)
    .where(and(eq(subscriptions.userId, args.userId), eq(subscriptions.status, "active")));
  for (const sub of existing) {
    await db
      .update(subscriptions)
      .set({ status: "expired", updatedAt: new Date() })
      .where(eq(subscriptions.id, sub.id));
  }

  const [sub] = await db
    .insert(subscriptions)
    .values({
      userId: args.userId,
      planId: args.planId,
      status: "active",
      interval: args.interval,
      startedAt: new Date(),
      currentPeriodEnd: computePeriodEnd(args.interval),
    })
    .returning();

  if (args.paymentId) {
    await db
      .update(payments)
      .set({ subscriptionId: sub.id })
      .where(eq(payments.id, args.paymentId));
  }

  await notify(
    args.userId,
    "membership",
    "membership_active",
    `Your ${plan[0].name} membership is active`,
    `Your subscription to the ${plan[0].name} plan (${args.interval}) is now active until ${sub.currentPeriodEnd?.toDateString()}.`,
    "/dashboard/billing",
    { email: true }
  );
  await logActivity(args.userId, "subscription.activated", "subscription", sub.id, { plan: plan[0].slug });
  await logAudit(args.actorId ?? args.userId, "subscription.activated", "subscription", sub.id);
  return sub;
}

export async function recordWebhookEvent(
  provider: PaymentProviderId,
  eventId: string,
  payload: string,
  signatureOk: boolean
) {
  try {
    const [event] = await db
      .insert(paymentWebhookEvents)
      .values({ provider, eventId, payload, signatureOk })
      .returning();
    return event;
  } catch {
    // unique(provider, eventId) -> duplicate delivery; idempotent
    const existing = await db
      .select()
      .from(paymentWebhookEvents)
      .where(and(eq(paymentWebhookEvents.provider, provider), eq(paymentWebhookEvents.eventId, eventId)))
      .limit(1);
    return existing[0] ?? null;
  }
}

export async function latestSubscription(userId: string) {
  const rows = await db
    .select({ sub: subscriptions, plan: membershipPlans })
    .from(subscriptions)
    .innerJoin(membershipPlans, eq(membershipPlans.id, subscriptions.planId))
    .where(eq(subscriptions.userId, userId))
    .orderBy(desc(subscriptions.createdAt))
    .limit(5);
  return rows;
}

export async function paymentHistory(userId: string) {
  return db
    .select()
    .from(payments)
    .where(eq(payments.userId, userId))
    .orderBy(desc(payments.createdAt))
    .limit(25);
}

export async function revenueSummary() {
  const rows = await db
    .select({ total: sql<number>`coalesce(sum(amount),0)::int`, count: sql<number>`count(*)::int` })
    .from(payments)
    .where(eq(payments.status, "completed"));
  return rows[0] ?? { total: 0, count: 0 };
}

/* ------------------------------- Admin metrics ------------------------------ */

export async function adminUserLookup(email: string) {
  const rows = await db.select().from(users).where(eq(users.email, email)).limit(1);
  return rows[0] ?? null;
}
